from pathlib import Path
path = Path('styles.css')
teeth = 22
n = 2 * teeth
pts = []
for side in range(4):
    for i in range(n):
        x = round(i / n * 100, 2)
        y = 1.6 * (i % 2)
        pair = [(x, y), (100-y, x), (100-x, 100-y), (y, 100-x)][side]
        pts.append(' '.join(f'{v:g}%' for v in pair))
lines = [', '.join(pts[i:i+11]) for i in range(0, len(pts), 11)]
with path.open('a') as css:
    css.write('\\n.fabric {\\n  --pinked-edge: polygon(\\n    ' + ',\\n    '.join(lines) + '\\n  );\\n}\\n')
PY"

